// Corta cada documento markdown (salida de LlamaParse) en fragmentos por sección.
// Cada fragmento lleva adelante "Documento + Sección" para que el embedding sepa de qué habla
// (así "Cardiología" queda junto a sus profesionales). Secciones largas se parten por párrafos
// y las tablas largas por filas, repitiendo el encabezado de la tabla.
const MAX = 1500;
const out = [];

function partirTabla(tabla) {
  const filas = tabla.split('\n');
  const head = filas.slice(0, 2).join('\n');
  const piezas = [];
  let cur = [];
  for (const f of filas.slice(2)) {
    if ((head + '\n' + cur.concat(f).join('\n')).length > MAX && cur.length) { piezas.push(head + '\n' + cur.join('\n')); cur = []; }
    cur.push(f);
  }
  if (cur.length) piezas.push(head + '\n' + cur.join('\n'));
  return piezas;
}

// LlamaParse devuelve las tablas complejas como HTML: las pasamos a tabla markdown (una fila por línea).
function htmlTablaAMarkdown(html) {
  const limpiar = s => s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').replace(/\|/g, '/').trim();
  const filas = [...html.matchAll(/<tr[\s\S]*?<\/tr>/g)].map(tr =>
    [...tr[0].matchAll(/<t[hd][^>]*>([\s\S]*?)<\/t[hd]>/g)].map(c => limpiar(c[1])));
  if (!filas.length) return limpiar(html);
  const sep = filas[0].map(() => '---');
  return [filas[0], sep, ...filas.slice(1)].map(f => '| ' + f.join(' | ') + ' |').join('\n');
}

for (const item of $input.all()) {
  const { source, file } = item.json;
  const markdown = item.json.markdown.replace(/<table[\s\S]*?<\/table>/g, t => '\n' + htmlTablaAMarkdown(t) + '\n');
  let ruta = [];   // pila de títulos: [h1, h2, h3, ...]
  let buf = [];

  const flush = () => {
    const cuerpo = buf.join('\n').trim();
    buf = [];
    if (!cuerpo) return;
    const section = ruta.filter(Boolean).join(' > ') || source;
    const header = `Documento: ${source}\nSección: ${section}\n\n`;
    const parrafos = cuerpo.split(/\n\s*\n/).flatMap(p => (p.length > MAX && p.trim().startsWith('|')) ? partirTabla(p.trim()) : [p]);
    let cur = '';
    for (const p of parrafos) {
      if (cur && (cur.length + p.length + 2) > MAX) { out.push({ json: { text: header + cur, source, section, file } }); cur = p; }
      else cur = cur ? cur + '\n\n' + p : p;
    }
    if (cur) out.push({ json: { text: header + cur, source, section, file } });
  };

  for (const linea of markdown.split('\n')) {
    const m = linea.match(/^(#{1,6})\s+(.*)$/);
    if (m) {
      flush();
      const nivel = m[1].length;
      ruta = ruta.slice(0, nivel - 1);
      ruta[nivel - 1] = m[2].replace(/\*\*/g, '').trim();
    } else {
      buf.push(linea);
    }
  }
  flush();
}
return out;

