// Junta lo que el validador necesita: pregunta, respuesta y los fragmentos que devolvió la herramienta.
const steps = $json.intermediateSteps || [];
const frags = steps
  .filter(s => s.action && s.action.tool === 'consultar_conocimiento')
  .map(s => typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation));
return [{ json: {
  pregunta: $('Normalizar entrada').first().json.mensaje,
  respuesta: $json.output || '',
  fragmentos: frags.length ? frags.join('\n\n=====\n\n') : '(el asistente no consultó la base documental)',
  busquedas: frags.length
} }];

// Si el validador aprueba, sale la respuesta del agente; si la rechaza, sale una respuesta segura.
// Si el validador falla (sin JSON válido), no se bloquea la respuesta: queda marcada como "no disponible".
const p = $('Preparar validación').first().json;
let v = {};
try {
  const raw = String($json.output ?? $json.text ?? '');
  const m = raw.match(/\{[\s\S]*\}/);
  v = JSON.parse(m ? m[0] : raw);
} catch (e) { v = {}; }
const disponible = typeof v.aprobado === 'boolean';
const aprobado = disponible ? v.aprobado : true;
const SEGURA = 'No cuento con ese dato en la documentación de la clínica. Te sugiero comunicarte con la Central de Turnos.';
return [{ json: {
  output: aprobado ? p.respuesta : SEGURA,
  validacion: disponible ? (aprobado ? 'aprobada' : 'rechazada') : 'no disponible',
  motivo: v.motivo || (disponible ? '' : 'el validador no devolvió un JSON válido'),
  respuesta_original: p.respuesta,
  busquedas: p.busquedas
} }];
